def authorization_decision(current_scheme: str, current_host: str, current_port: str, next_scheme: str, next_host: str, next_port: str, authorization: str) -> str:
    if authorization == "none":
        return "absent"
    if current_host == next_host:
        if current_scheme == "https" and next_scheme == "http":
            return "strip"
        return "keep"
    return "strip"

rust.credentials.rs:
pub fn authorization_decision(current_scheme: &str, current_host: &str, _current_port: &str, next_scheme: &str, next_host: &str, _next_port: &str, authorization: &str) -> &'static str {
    if authorization == "none" {
        return "absent";
    }
    if current_host == next_host {
        if current_scheme == "https" && next_scheme == "http" {
            return "strip";
        }
        return "keep";
    }
    "strip"
}

parley.classification.par:
to config_kind with token as text giving text:
    if token is "missing":
        give back "missing"
    if token is "null":
        give back "null"
    if token is "empty":
        give back "empty"
    if token is "one" or token is "two" or token is "three":
        give back "list"
    give back "invalid"

python.classification.py:
def config_kind(token: str) -> str:
    if token == "missing":
        return "missing"
    if token == "null":
        return "null"
    if token == "empty":
        return "empty"
    if token in ("one", "two", "three"):
        return "list"
    return "invalid"

rust.classification.rs:
pub fn config_kind(token: &str) -> &'static str {
    match token {
        "missing" => "missing",
        "null" => "null",
        "empty" => "empty",
        "one" | "two" | "three" => "list",
        _ => "invalid",
    }
}

parley.origin.par:
to redirect_origin with trusted as text, request_scheme as text, request_host as text, request_port as text, forwarded_scheme as text, forwarded_host as text, forwarded_port as text giving text:
    let scheme be (selected_header with trusted, forwarded_scheme, request_scheme)
    let host be (selected_header with trusted, forwarded_host, request_host)
    let port be (selected_header with trusted, forwarded_port, request_port)
    give back scheme + "://" + host + ":" + port

rust.origin.rs:
use crate::headers::selected_header;

pub fn redirect_origin<'a>(trusted: &str, request_scheme: &'a str, request_host: &'a str, request_port: &'a str, forwarded_scheme: &'a str, forwarded_host: &'a str, forwarded_port: &'a str) -> String {
    let scheme = selected_header(trusted, forwarded_scheme, request_scheme);
    let host = selected_header(trusted, forwarded_host, request_host);
    let port = selected_header(trusted, forwarded_port, request_port);
    format!("{scheme}://{host}:{port}")
}

